 display: none !important;
 }
}


.talkon-navigation-link {
 border-bottom: 3px solid transparent;
 outline: none !important;
 transition: 0.3s;
}

.talkon-navigation-link a,
.talkon-navigation-link a:active,
.talkon-navigation-link a:hover {
 text-decoration: none !important;
 outline: none !important;
}

.talkon-navigation-link:has(a[aria-current="page"]) {
 border-bottom: 3px solid #FEC553 !important;
}

.talkon-navigation-link:hover {
