.position-relative {
 position: relative;
}

@media (prefers-reduced-motion: no-preference) {

 @keyframes slide-from-left {
 0% {
 left: -70%;
 }

 40% {
 left: 0%;
 }

 60% {
 left: 0%;
 }

 100% {
 left: -70%;
 }
 }

 @keyframes slide-from-right {
 0% {
 right: -70%;
 }

 40% {
 right: 0%;
 }

 60% {
 right: 0%;
 }

 100% {
 right: -70%;
 }
 }

 @keyframes fade-on-scroll {
 0% {
 opacity: 1
 }

 90% {
 opacity: 1
 }

 100% {
 opacity: 0
 }
 }

 .slide-from-left {
 animation: slide-from-left linear both;
 animation-timeline: view();
 }

 .slide-from-right {
 animation: slide-from-right linear both;
 animation-timeline: view();
 }

 .fade-on-scroll {
 animation: fade-on-scroll;
 animation-timeline: view();
 }
}

@media only screen and (max-width: 1200px) {
 .slide-from-left {
 animation: none;
 }

 .slide-from-right {
 animation: none;
 }
}


